mapper.select:
select hfca.CONTRACT_ATTACHMENT_CATEGORY, hfca.DOCUMENT_NAME, ( select sf.file_id from sys_attachment sa, sys_file sf
hfca.CONTRACT_ATTACHMENT_ID||''= sa.source_key
AND sa.source_type = #{sourceType}
AND sa.attachment_id = sf.attachment_id
) file_id, ( SELECT wm_concat ( sf.file_name ) FROM sys_attachment sa, sys_file sf
hfca.CONTRACT_ATTACHMENT_ID||''= sa.source_key
AND sa.source_type = #{sourceType}
AND sa.attachment_id = sf.attachment_id
) file_name, hfca.description, hfca.CONTRACT_ATTACHMENT_ID FROM CON_CONTRACT_ATTACHMENT hfca
1 = 1
and hfca.CONTRACT_ATTACHMENT_CATEGORY=#{contractAttachmentCategory}
and hfca.CONTRACT_ID=#{contractId}
ORDER BY last_update_date ASC

SELECT
    cca.*,
    (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id
    and faam.table_name = 'CON_CONTRACT_ATTACHMENT' and faam.table_pk_value = cca.contract_attachment_id
    ) file_name
FROM
    con_contract_attachment cca
WHERE 1=1

    and cca.source_type=#{sourceType}


    and cca.source_id=#{sourceId}

select hfca.CONTRACT_ATTACHMENT_CATEGORY, hfca.DOCUMENT_NAME, hfca.description, hfca.CONTRACT_ATTACHMENT_ID, hfca.CREATION_DATE upload_date, (select su.description from sys_user su where hfca.last_updated_by = su.user_id) as upload_person, (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'CON_CONTRACT_ATTACHMENT' and faam.table_pk_value = hfca.contract_attachment_id ) file_name FROM CON_CONTRACT_ATTACHMENT hfca where hfca.CONTRACT_ATTACHMENT_CATEGORY='CON_CONTRACT_LEND'
and hfca.CONTRACT_ID=#{contractId}
ORDER BY last_update_date ASC

SELECT ca.*, (SELECT group_concat(sf.FILE_NAME) FROM fnd_atm_attachment sf, fnd_atm_attachment_multi sa WHERE sa.ATTACHMENT_ID = sf.ATTACHMENT_ID AND ca.contract_attachment_id = sa.table_pk_value AND upper(sa.table_name) = 'CON_CONTRACT') file_names, (SELECT group_concat(sf.file_type_code) FROM fnd_atm_attachment sf, fnd_atm_attachment_multi sa WHERE sa.ATTACHMENT_ID = sf.ATTACHMENT_ID AND ca.contract_attachment_id = sa.table_pk_value AND upper(sa.table_name) = 'CON_CONTRACT') file_type, (SELECT group_concat(sf.attachment_id) FROM fnd_atm_attachment sf, fnd_atm_attachment_multi sa WHERE sa.ATTACHMENT_ID = sf.ATTACHMENT_ID AND ca.contract_attachment_id = sa.table_pk_value AND upper(sa.table_name) = 'CON_CONTRACT') file_id, (SELECT group_concat(sa.table_pk_value) FROM fnd_atm_attachment sf, fnd_atm_attachment_multi sa WHERE sa.ATTACHMENT_ID = sf.ATTACHMENT_ID AND ca.contract_attachment_id = sa.table_pk_value AND upper(sa.table_name) = 'CON_CONTRACT') source_key FROM con_contract_attachment ca
1=1
and ca.contract_id = #{contractId,jdbcType=BIGINT}
and ca.contract_attachment_category = #{contractAttachmentCategory,jdbcType=VARCHAR}
and ca.process_instance_id is null
and ca.process_instance_id = #{processInstanceId,jdbcType=VARCHAR}
and ca.ref_d01 = #{refD01,jdbcType=DATE}

select m.record_id, m.table_name, m.table_pk_value, m.attachment_id,
       m.created_by, m.creation_date, m.last_updated_by, m.last_update_date
from FND_ATM_ATTACHMENT_MULTI m where m.TABLE_NAME = #{tableName} and m.TABLE_PK_VALUE = #{tablePkValue}
